import {defaults,bounds,model,sensitivity,simulate} from './model.js';
const $=s=>document.querySelector(s),pct=x=>(x*100).toFixed(1)+'%',money=x=>'$'+x.toFixed(1)+'m';let a={...defaults},seed=42,notes=[];
try{const saved=JSON.parse(localStorage.getItem('dealcraft-a'));if(saved){model(saved);a=saved;}notes=JSON.parse(localStorage.getItem('dealcraft-notes'))||[];notes=notes.filter(n=>{try{return typeof n.name==='string'&&!!model(n.a)}catch{return false}}).slice(0,8);}catch{}
const groups=[['TRANSACTION',[['entry','Entry multiple','×',.5],['exit','Exit multiple','×',.5],['leverage','Entry debt / EBITDA','×',.25],['interest','Interest rate','%',.5]]],['OPERATING STRATEGY',[['growth','Organic revenue growth','%',1],['margin','EBITDA margin','%',1],['synergy','Run-rate cost synergies','m',1],['integration','Integration cost','m',1]]],['PRODUCT LEVERS',[['retention','Revenue retention','%',1],['pricing','Annual pricing uplift','%',1],['crossSell','Cross-sell rate','%',1]]]];
function controls(){ $('#controls').innerHTML=groups.map(([name,items])=>`<div class="control-group">${name}</div>`+items.map(([k,label,u,step])=>`<div class="control"><label for="${k}">${label}<output id="out-${k}">${a[k]}${u}</output></label><input id="${k}" type="range" min="${bounds[k][0]}" max="${bounds[k][1]}" step="${step}" value="${a[k]}" data-unit="${u}"></div>`).join('')).join('');for(const input of document.querySelectorAll('input')) input.addEventListener('input',()=>{a[input.id]=+input.value;$('#out-'+input.id).textContent=input.value+input.dataset.unit;document.querySelectorAll('[data-preset]').forEach(x=>x.classList.remove('active'));render();});}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function render(){const m=model(a),last=m.years.at(-1);try{localStorage.setItem('dealcraft-a',JSON.stringify(a))}catch{}
$('#metrics').innerHTML=[['Equity IRR',pct(m.irr),'20% illustrative hurdle'],['Money multiple',m.moic.toFixed(2)+'×','Year-five equity proceeds'],['Sponsor equity',money(m.equity),'Includes transaction fees'],['Exit net debt',money(last.debt-last.cash),'Debt less accumulated cash']].map(([l,v,s])=>`<div class="metric"><span>${l}</span><strong>${v}</strong><small>${s}</small></div>`).join('');
const max=Math.max(m.debt0,...m.years.map(y=>Math.max(y.ebitda,y.debt)),40)*1.15,sy=v=>180-v/max*150;const points=[{year:0,ebitda:24,debt:m.debt0},...m.years],line=k=>points.map((y,i)=>`${60+i*110},${sy(y[k])}`).join(' ');
$('#chart').innerHTML=`<svg class="chart" viewBox="0 0 660 215" role="img" aria-label="EBITDA and debt over five years. Final EBITDA ${money(last.ebitda)}, debt ${money(last.debt)}"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#d4e8c4" stop-opacity=".8"/><stop offset="1" stop-color="#eef5e8" stop-opacity=".2"/></linearGradient></defs>${[0,1,2,3].map(i=>{const v=max*i/3;return `<line x1="60" x2="620" y1="${sy(v)}" y2="${sy(v)}" stroke="#e7ece4" stroke-dasharray="3 4"/><text x="0" y="${sy(v)+4}" font-size="10" fill="#83917f">$${v.toFixed(0)}m</text>`}).join('')}<polygon points="60,180 ${line('ebitda')} 610,180" fill="url(#area)"/><polyline points="${line('debt')}" fill="none" stroke="#7e9ab0" stroke-width="2" stroke-dasharray="5 4"/><polyline points="${line('ebitda')}" fill="none" stroke="#287e56" stroke-width="3"/>${points.map((y,i)=>`<circle cx="${60+i*110}" cy="${sy(y.ebitda)}" r="4" fill="#287e56"/><text x="${60+i*110}" y="205" text-anchor="middle" font-size="10" fill="#83917f">${i?'Year '+i:'Entry'}</text>`).join('')}</svg>`;
$('#verdict').innerHTML=`<div class="verdict ${m.liquidityShortfall?'warn':''}"><b>${m.liquidityShortfall?'⚠ Funding gap':m.irr>=.2?'↗ Clears the hurdle':'↘ Below the hurdle'}</b><span>${m.liquidityShortfall?'At least one year has negative accumulated cash. Additional funding is needed; headline IRR does not include that capital.':`The model produces ${pct(m.irr)} IRR against a 20% illustrative hurdle. ${a.exit<a.entry?'Returns must overcome multiple compression.':'Test a lower exit multiple before relying on this outcome.'}`}</span></div>`;
const matrix=sensitivity(a);$('#heatmap').innerHTML='<div class="heat"><div class="axis">Exit / growth</div>'+[-2,-1,0,1,2].map(x=>`<div class="axis">${Math.max(-10,Math.min(30,a.growth+x*2))}%</div>`).join('')+matrix.map((row,i)=>`<div class="axis">${Math.max(6,Math.min(18,a.exit+i-2)).toFixed(1)}×</div>`+row.map((v,j)=>`<div class="${i===2&&j===2?'center':''}" style="background:${v>=.2?'#d9ebc3':v>=.1?'#eef2d9':'#f4e3ce'}">${pct(v)}</div>`).join('')).join('')+'</div>';
const sim=simulate(a,1000,seed),bins=Array(24).fill(0),lo=sim.values[0],hi=sim.values.at(-1);sim.values.forEach(v=>bins[Math.min(23,Math.floor((v-lo)/(hi-lo||1)*24))]++);$('#simulation').innerHTML=`<div class="sim-stats">${[['10th percentile',pct(sim.p10)],['Median IRR',pct(sim.p50)],['90th percentile',pct(sim.p90)],['Trials ≥ 20% IRR',pct(sim.hurdle)],['Trials losing equity',pct(sim.loss)]].map(([l,v])=>`<div><strong>${v}</strong><span>${l}</span></div>`).join('')}</div><div class="histogram" role="img" aria-label="Distribution of simulated returns">${bins.map(n=>`<i style="height:${n/Math.max(...bins)*100}%"></i>`).join('')}</div><div class="hist-label"><span>${pct(lo)}</span><span>Illustrative simulation · seed ${seed}</span><span>${pct(hi)}</span></div>`;
const rows=[['Revenue','revenue'],['Cost synergies','synergy'],['EBITDA','ebitda'],['Cash interest','interest'],['Cash taxes','tax'],['Capital expenditure','capex'],['Change in working capital','nwc'],['Integration costs','integration'],['Free cash flow','fcf'],['Debt repayment','paydown'],['Closing debt','debt'],['Accumulated cash','cash']];$('#schedule').innerHTML='<table><thead><tr><th>USD millions</th>'+m.years.map(y=>`<th>Year ${y.year}</th>`).join('')+'</tr></thead><tbody>'+rows.map(([l,k])=>`<tr><td>${l}</td>${m.years.map(y=>`<td>${y[k].toFixed(1)}</td>`).join('')}</tr>`).join('')+'</tbody></table>';notebook();}
function notebook(){const host=$('#notebook');host.replaceChildren();if(!notes.length){host.innerHTML='<p class="empty">Save a scenario to compare underwriting choices. Up to eight scenarios are stored locally.</p>';return}notes.forEach((n,i)=>{const m=model(n.a),row=document.createElement('div');row.className='notebook-row';const txt=document.createElement('div');const title=document.createElement('b');title.textContent=n.name;const sub=document.createElement('small');sub.textContent=`${pct(m.irr)} IRR · ${m.moic.toFixed(2)}× MOIC · ${n.a.entry}× entry / ${n.a.exit}× exit${m.liquidityShortfall?' · Funding gap':''}`;txt.append(title,sub);const actions=document.createElement('div');for(const [label,fn] of [['Load',()=>{a={...n.a};controls();render();toast('Scenario loaded')}],['Delete',()=>{notes.splice(i,1);persistNotes();notebook()}]]){const b=document.createElement('button');b.textContent=label;b.setAttribute('aria-label',label+' '+n.name);b.onclick=fn;actions.append(b)}row.append(txt,actions);host.append(row)})}
function persistNotes(){try{localStorage.setItem('dealcraft-notes',JSON.stringify(notes))}catch{toast('Storage unavailable; scenarios retained for this session')}}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#save').onclick=()=>{if(notes.length>=8)return toast('Delete a scenario to make room.');notes.push({name:`Scenario ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}`,a:{...a}});persistNotes();notebook();toast('Scenario saved locally')};
$('#reset').onclick=()=>{a={...defaults};controls();render();toast('Base assumptions restored')};
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{a={...defaults,...({base:{},upside:{growth:18,retention:97,synergy:12,exit:12},downside:{growth:3,retention:88,synergy:3,exit:8,integration:22}}[b.dataset.preset])};controls();document.querySelectorAll('[data-preset]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#run').onclick=()=>{seed++;render();toast('Simulation updated')};
$('#csv').onclick=()=>{const m=model(a),keys=Object.keys(m.years[0]);download('dealcraft-model.csv','metric,assumption\n'+Object.entries(a).map(([k,v])=>k+','+v).join('\n')+'\n\n'+keys.join(',')+'\n'+m.years.map(y=>keys.map(k=>y[k]).join(',')).join('\n'),'text/csv')};
$('#memo').onclick=()=>{const m=model(a),s=simulate(a,1000,seed),last=m.years.at(-1);download('dealcraft-investment-memo.md',`# Investment committee memo — Atlas acquisition\n\nFictional educational case. USD millions.\n\n## Decision\n${m.liquidityShortfall?'Funding gap: resolve liquidity before considering returns.':m.irr>=.2?'Passes the illustrative 20% return screen; requires further diligence.':'Does not meet the illustrative 20% return screen.'}\n\n## Transaction\nEntry EV ${money(m.ev)}; debt ${money(m.debt0)}; fees ${money(m.fees)}; sponsor equity ${money(m.equity)}.\n\n## Return\nFive-year IRR ${pct(m.irr)}; MOIC ${m.moic.toFixed(2)}x; exit EV ${money(m.exitEV)}; proceeds ${money(m.proceeds)}. Final debt ${money(last.debt)}; cash ${money(last.cash)}.\n\n## Assumptions\n${Object.entries(a).map(([k,v])=>'- '+k+': '+v).join('\n')}\n\n## Risk range\n1,000 illustrative trials, seed ${seed}: P10 ${pct(s.p10)}, median ${pct(s.p50)}, P90 ${pct(s.p90)}. ${pct(s.hurdle)} clear 20%; ${pct(s.loss)} lose equity. Independent, uncalibrated distributions.\n\n## Diligence questions\n- Validate customer cohort retention and willingness to pay before assuming pricing uplift.\n- Assign owners, timelines, and evidence to cost and cross-sell synergies.\n- Confirm debt terms, working capital needs, and integration cash costs.\n- Stress correlated downside and financing availability.\n\n## Model limitations\nExit-only equity return. No purchase accounting, tax loss carryforwards, debt covenants, interest caps, or financing fees. Funding deficits do not include additional sponsor injections. Simulation is illustrative.\n`, 'text/markdown')};controls();render();
